 const [authReady,setAuthReady]=useState(!isSupabaseConfigured); const [authError,setAuthError]=useState(""); const [tgNumber,setTgNumber]=useState(""); const [loginCode,setLoginCode]=useState(""); const [codeSent,setCodeSent]=useState(false); const [authBusy,setAuthBusy]=useState(false); const [mfaLoginRequired,setMfaLoginRequired]=useState(false); const [mfaLoginFactorId,setMfaLoginFactorId]=useState(""); const [mfaLoginChallengeId,setMfaLoginChallengeId]=useState(""); const [mfaLoginCode,setMfaLoginCode]=useState(""); const [mfaLoginBusy,setMfaLoginBusy]=useState(false); const [mfaLoginError,setMfaLoginError]=useState(""); const [mfaCheckedUser,setMfaCheckedUser]=useState("");
 const [chats,setChats]=useState<Chat[]>([]); const [messages,setMessages]=useState<Message[]>([]); const [uploadBusy,setUploadBusy]=useState(false); const fileInputRef=useRef<HTMLInputElement|null>(null); const [editingMessageId,setEditingMessageId]=useState<string|null>(null); const [editingDraft,setEditingDraft]=useState(""); const [messageBusy,setMessageBusy]=useState(false);
 const [activeId,setActiveId]=useState(""); const [draft,setDraft]=useState(""); const [query,setQuery]=useState(""); const [tab,setTab]=useState("Все"); const [mobileChat,setMobileChat]=useState(false); const [mobileTab,setMobileTab]=useState<"chats"|"contacts"|"settings"|"profile">("chats");
 const [modal,setModal]=useState<"menu"|"direct"|"group"|"channel"|null>(null); const [newTitle,setNewTitle]=useState(""); const [newUsername,setNewUsername]=useState(""); const [actionError,setActionError]=useState(""); const [busy,setBusy]=useState(false); const [profileName,setProfileName]=useState(""); const [profileUsername,setProfileUsername]=useState(""); const [settingsOpen,setSettingsOpen]=useState(false); const [settingsSection,setSettingsSection]=useState<"home"|"account"|"chats"|"privacy"|"notifications"|"storage"|"folders"|"stars"|"gifts">("home"); const [settingsPrefs,setSettingsPrefs]=useState({theme:"dark",animations:true,lastSeen:true,readReceipts:true,messageNotifications:true,groupNotifications:true,sounds:true,previews:true,autoDownload:false,cloudPassword:false,autoDelete:false,messageDeletePeriod:"1 день",passcode:false,passkeys:false,loginEmail:false,phoneVisibility:"Никто",lastSeenVisibility:"Никто",photoVisibility:"Никто (+1)",forwardVisibility:"Никто",callsVisibility:"Никто",voiceVisibility:"Все",messageVisibility:"Все",birthdayVisibility:"Контакты",giftsVisibility:"Все",bioVisibility:"Все",musicVisibility:"Все",inviteVisibility:"Все",deleteAfter:"18 месяцев"}); const [privacyDialog,setPrivacyDialog]=useState<string|null>(null); const [settingsOwner,setSettingsOwner]=useState(""); const [settingsSyncStatus,setSettingsSyncStatus]=useState(""); const [deviceActionBusy,setDeviceActionBusy]=useState(false); const [blockedUsers,setBlockedUsers]=useState<{id:string;tg_id:string;display_name:string}[]>([]); const [blockInput,setBlockInput]=useState(""); const [blockBusy,setBlockBusy]=useState(false); const [blockError,setBlockError]=useState(""); const [mfaFactors,setMfaFactors]=useState<any[]>([]); const [mfaFactorId,setMfaFactorId]=useState(""); const [mfaQr,setMfaQr]=useState(""); const [mfaSecret,setMfaSecret]=useState(""); const [mfaCode,setMfaCode]=useState(""); const [mfaBusy,setMfaBusy]=useState(false); const [mfaMessage,setMfaMessage]=use